    uint32_t h = seed ^ (n * m);

    // Process 4 bytes at a time
    const uint32_t* data_32 = reinterpret_cast<const uint32_t*>(data);
    while (n >= 4) {
        h += *data_32;
        h *= m;
        h ^= (h >> 16);
        data_32++;
        n -= 4;
    }

    // Process remaining bytes
    const char* data_char = reinterpret_cast<const char*>(data_32);
    switch (n) {
        case 3:
            h += static_cast<uint32_t>(static_cast<unsigned char>(data_char[2]) << 16);
